"""Generate fixtures/src/entropy_blob_data.h: 4 KiB of seeded pseudo-random bytes.

The output is committed. Re-running this script must produce identical bytes,
because the seed is fixed. Usage (from the repository root):

    python3 fixtures/build/gen_blob.py
"""

import random
from pathlib import Path

SEED = 0xB17A5
SIZE = 4096
OUT = Path(__file__).resolve().parent.parent / "src" / "entropy_blob_data.h"


def main() -> None:
    data = random.Random(SEED).randbytes(SIZE)
    lines = [
        "// Generated by fixtures/build/gen_blob.py (seed 0xB17A5). Do not edit.",
        f"#define BYTASM_BLOB_SIZE {SIZE}",
        "#define BYTASM_BLOB_BYTES { \\",
    ]
    for start in range(0, SIZE, 16):
        chunk = ", ".join(f"0x{b:02x}" for b in data[start : start + 16])
        lines.append(f"  {chunk}, \\")
    lines.append("}")
    OUT.write_text("\n".join(lines) + "\n", encoding="ascii")


if __name__ == "__main__":
    main()
